    else:
        pattern_rows = grid[lr+1:H]

    if sc == 0:
        pattern = [row[0:lc] for row in pattern_rows]
    else:
        pattern = [row[lc+1:] for row in pattern_rows]

    # Convert pattern: noise positions become line color
    transformed_pattern = []
    for row in pattern:
        transformed_row = []
        for val in row:
            transformed_row.append(LC if val == noise_color else Bg)
        transformed_pattern.append(transformed_row)

