    # Place transformed pattern in source quadrant position
    if sr == 0 and sc == 0:  # TL
        out[:lr][0:lc] = transformed_pattern
    elif sr == 0 and sc == 1:  # TR
        for r in range(lr):
            for c in range(lc, W):
                out[r][c] = transformed_pattern[lr-1-r][c-lc-1]
        out[:lr][lc:] = transformed_pattern
    elif sr == 1 and sc == 0:  # BL
        for r in range(lr, H):
            for c in range(lc):
                out[r][c] = transformed_pattern[r-lr-1][c]
